# The metric catalogue. Each metric's yearly values are worked out in dictionary.py
# under the same code; a metric with status Dormant has none (permanent rules: no
# estimate fills a gap).
def M(code, name, description, use, kind, unit, grain, frequency, owner, source, calculation,
      where, inputs, depends=(), used_by=(), measure="", status="Active", classification="Internal",
      public="No"):
    return dict(code=code, theme=THEMES[code.split("_")[0]], name=name, description=description,
                use=use, kind=kind, status=status, unit=unit, grain=grain, frequency=frequency,
                owner=owner, source=source, calculation=calculation, where=where, inputs=list(inputs),
                depends=list(depends), used_by=list(used_by), measure=measure,
                classification=classification, public=public)


